import{z as o,x as s,o as B,c as d,q as r,j as i,D as n,d as e,s as l,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"深度微观结构信号","description":"","frontmatter":{"title":"深度微观结构信号","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/dp-deep-micro-signals.md","filePath":"quant/dp-deep-micro-signals.md","lastUpdated":1791063341000}'),p={name:"quant/dp-deep-micro-signals.md"};function u(m,a,h,f,c,C){const t=s("Mermaid");return B(),d("div",null,[a[2]||(a[2]=r('<h1 id="深度微观结构信号" tabindex="-1">深度微观结构信号 <a class="header-anchor" href="#深度微观结构信号" aria-label="Permalink to &quot;深度微观结构信号&quot;">​</a></h1><div class="epigraph"><p>微观结构信号不按准确率结算，按扣掉冲击与成本后剩下的分币结算；深度网络的正当性是把 OFI 没写进方程的非线性与跨档结构学出来——前提是它们在样本外还存在。</p><footer>—— 据 Cont, Kukanov and Stoikov, Review of Financial Studies, 2014；Sirignano and Cont, Quantitative Finance, 2019 整理</footer></div><p><a href="/quant/dp-deep-vol">上一课</a>把深度波动率的口径钉在基线上：与 HAR 同协议、用 QLIKE 交卷。本课把时钟从日频拨到毫秒，对象换成订单流与簿状态本身。<a href="/quant/ofi-cont">订单流冲击</a>（OFI）与<a href="/quant/microprice">微观价格</a>是线性时代的答案：几列加权和就能解释短时中点变动的一大块。<a href="/quant/deeplob-cnn-lstm">DeepLOB</a> 一线把整个档位张量交给卷积与注意力，<a href="/quant/neural-hawkes-orderflow">Neural Hawkes</a> 把事件流交给连续时间循环网络。本课不重讲这些架构，而是问它们的共同考题：学到的表示在扣掉线性基线、延迟与冲击之后，还剩多少可实现的信号。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>线性摘要已经拿走了大头：OFI 把最优档的挂、撤、成交合成一个流量，微观价格按队列权重移动中点，<a href="/quant/queue-imbalance-alpha">队列失衡</a>直接预测短窗方向。深度模型的候选增量有三类：跨档结构（第二档的挂撤如何预示第一档的耗尽）、非线性状态切换（价差从一个 tick 变宽时，同样的流量含义翻转）、事件流的时间记忆（超出状态能解释的自激）。每类都要与状态依赖做嵌套检验——<a href="/quant/neural-hawkes-orderflow">Neural Hawkes 课</a>的口径原样适用：加入队列与价差状态后增益消失，说明学到的是状态不是记忆。更大的缺口在目标定义：中点方向准确率的天花板由价差几何决定（<a href="/quant/deep-lob-leakage">深度 LOB 泄漏</a>的警告），诚实的评测要落到经济价值——这个信号若喂给执行层，能省下多少成本。</p><p><span class="marginnote">术语翻译：OFI（订单流冲击）就是给簿的变动记流水账——新增买单加分、撤买单减分、卖单打进也减分，把最优档的挂、撤、成交合成一个净流量；这个流量对短时中点变动的线性回归，就是线性时代的「信号」。</span></p><h3 id="经济价值的算法" tabindex="-1">经济价值的算法 <a class="header-anchor" href="#经济价值的算法" aria-label="Permalink to &quot;经济价值的算法&quot;">​</a></h3><p>信号的价值不是准确率乘波动，而是：给定同一执行任务，用信号与不用信号各付多少<a href="/quant/implementation-shortfall">实现短缺</a>，差值再扣模型本身的成本。短窗信号的用途天然在执行侧而非持仓侧：毫秒到秒级的预测衰减太快，装不进日频组合。</p><p><span class="marginnote">数字实例：同一笔 1 万股的执行任务，不用信号付 8 个基点的实现短缺，用信号付 6 个基点；信号侧的服务器与数据费折合 0.5 个基点——净价值就是 1.5 个基点，而不是「方向准确率 58%」。</span></p><p><span class="marginnote">Sirignano 与 Cont 用同一架构跨多只股票训练，发现簿的局部特征相当「普适」。但普适的是条件结构，不是超额：跨券可迁移，不等于扣完成本还是正的。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>表示分两条流水线：快照流（档位张量）走卷积或注意力，事件流（限价、撤、成交）走点过程或连续时间 RNN，两者可拼接。标签按用途倒推：喂执行层就标「未来数笔内中点相对最优价的改进」，并按价差与深度状态分层报告——薄档与厚档、窄价差与宽价差分开交卷，混在一起的平均值掩盖的正是深度的条件结构。基线三件套必须同协议在场：OFI 线性回归、微观价格增量、恒预测。特征工程不因有网络而豁免：成交签名先按 <a href="/quant/lee-ready">Lee–Ready</a> 或<a href="/quant/bulk-volume-classification">批量体积分类</a>对齐，异常单与心跳剔除的规则写进数据管道——这些脏活的疏漏比架构选择更常决定成败。</p>',12)),(B(),i(A,null,{default:n(()=>[l(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SNAP%5B%22%E6%A1%A3%E4%BD%8D%E5%BC%A0%E9%87%8F%E5%BF%AB%E7%85%A7%22%5D%20--%3E%20REP%5B%22%E5%8D%B7%E7%A7%AF%20%2F%20%E6%B3%A8%E6%84%8F%E5%8A%9B%E8%A1%A8%E7%A4%BA%22%5D%0A%20%20EV%5B%22%E4%BA%8B%E4%BB%B6%E6%B5%81%22%5D%20--%3E%20REP2%5B%22%E7%82%B9%E8%BF%87%E7%A8%8B%20%2F%20CT-RNN%22%5D%0A%20%20REP%20--%3E%20VAL%5B%22%E7%BB%8F%E6%B5%8E%E4%BB%B7%E5%80%BC%EF%BC%9A%E5%86%B2%E5%87%BB%E5%90%8E%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20REP2%20--%3E%20VAL%0A%20%20LIN%5B%22OFI%20%2F%20%E5%BE%AE%E8%A7%82%E4%BB%B7%E6%A0%BC%E7%BA%BF%E6%80%A7%E5%9F%BA%E7%BA%BF%22%5D%20--%3E%20VAL%0A%20%20VAL%20--%3E%20GATE%7B%22%E6%89%A3%E6%88%90%E6%9C%AC%E5%90%8E%E4%B8%BA%E6%AD%A3%EF%BC%9F%22%7D%0A%20%20GATE%20--%3E%7C%E6%98%AF%7C%20EXEC%5B%22%E5%96%82%E7%BB%99%E6%89%A7%E8%A1%8C%E5%B1%82%EF%BC%8C%E4%B8%8B%E4%B8%80%E8%AF%BE%22%5D%0A%20%20GATE%20--%3E%7C%E5%90%A6%7C%20DIAG%5B%22%E9%99%8D%E7%BA%A7%E4%B8%BA%E8%AF%8A%E6%96%AD%E7%89%B9%E5%BE%81%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("为什么非线性可能真实存在：簿是状态机，价差与队列深度决定同样的订单流被解读成「耗尽前的补量」还是「知情撤退」，线性模型给不出这个切换；跨档替代与恢复也有真实的阈值结构。为什么它常常是假的：短窗信号与冲击同源——主动单既推动中点也搬走价格，模型在中点上赢的，正是要在执行里付出去的；回放数据里学到的「可预测性」还建立在自己不在场的假设上，自己参与后开环统计立即失效，这是"),E("a",{href:"/quant/trading-mdp-pitfalls"},"交易 MDP 陷阱"),e("的第一条。所以评测的最后一步必须过冲击模型，而不是停在信息系数。")],-1)),a[5]||(a[5]=E("p",null,"「信号与冲击同源」这件事，一笔主动单就能画清楚：",-1)),(B(),i(A,null,{default:n(()=>[l(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20Trade%5B%22%E4%B8%80%E7%AC%94%E4%B8%BB%E5%8A%A8%E5%B8%82%E4%BB%B7%E5%8D%95%22%5D%20--%3E%20Mid%5B%22%E6%8E%A8%E5%8A%A8%E4%B8%AD%E7%82%B9%3A%20%E4%BF%A1%E6%81%AF%E5%B1%82%E8%B5%A2%22%5D%0A%20%20Trade%20--%3E%20Impact%5B%22%E6%90%AC%E8%B5%B0%E4%BB%B7%E6%A0%BC%3A%20%E6%89%A7%E8%A1%8C%E5%B1%82%E8%A6%81%E4%BB%98%22%5D%0A%20%20Mid%20--%3E%20Same%5B%22%E5%90%8C%E6%BA%90%3A%20%E8%B5%A2%E7%9A%84%E4%B8%8E%E4%BB%98%E7%9A%84%E6%9D%A5%E8%87%AA%E5%90%8C%E4%B8%80%E7%AC%94%E6%B5%81%22%5D%0A%20%20Impact%20--%3E%20Same%0A%20%20Same%20--%3E%20Eval%5B%22%E8%AF%84%E6%B5%8B%E5%BF%85%E9%A1%BB%E8%BF%87%E5%86%B2%E5%87%BB%E6%A8%A1%E5%9E%8B%2C%20%E4%B8%8D%E8%83%BD%E5%81%9C%E5%9C%A8%E4%BF%A1%E6%81%AF%E7%B3%BB%E6%95%B0%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">常见误区：容易把「回放里能预测中点」当成「实盘能赚钱」。回放里你不在场，别人的订单不会因为你而改变；一旦自己下单，别人会躲、簿会变，开环统计立刻作废。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写执行策略本身——信号到动作的转换是下一课的对象；也不做生成式仿真——拟合簿的测度交给定价单元。延迟是硬边界：馈源延迟几十毫秒，信号的全部增量可能恰好是延迟的镜像，<a href="/quant/deep-lob-leakage">深度 LOB 泄漏</a>的时间戳审计在此强制执行。开环评估的有效性以「自己不参与」为前提；任何把信号装进策略的说法，都要等执行课的闭环口径。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>深度微观信号的增量候选：跨档结构、价差状态切换、事件流记忆；逐项与线性基线嵌套比较。</li><li>评测终点是经济价值：同任务下执行成本的节省，不是中点方向准确率。</li><li>信号与冲击同源，信息层赢下的常常就是执行层要付的。</li><li>表示分快照流与事件流两条；数据清洗与签名对齐先于架构。</li><li>出处：Cont, Kukanov and Stoikov, <em>RFS</em>, 2014（OFI）；Sirignano and Cont, <em>Quantitative Finance</em>, 2019；Zhang, Zohren and Roberts, <em>IEEE TSP</em>, 2019（DeepLOB）。</li></ul>',5))])}const q=o(p,[["render",u]]);export{D as __pageData,q as default};
